  /** Show whether the site runs, its port, pid, database and agent version. */
  status?: boolean;
  /** Show the latest run's log (the site's console output); data.previous lists the logs of up to 2 runs before it. */
  logs?: boolean;
  /** With --logs: only the last N lines (default 200). */
  tail?: number;
  /** Stop the site (asks it to shut down through the agent, else SIGTERM on Unix; kills it after 20 s) and forget its token. */
