  /** Validate and show the before/after diff without saving anything. */
  dryRun?: boolean;
  /** Publish the new version. Default: save it as a draft, which changes nothing live. */
  publish?: boolean;
  /** Where an approval sequence applies (get shows approval), send the change for review instead of publishing: it is saved and the sequence starts, as the edit UI's Ready for Review does; publishing there is refused (exit 3). With --publish, content without a sequence is published as usual. */
  requestApproval?: boolean;
  /** Against a shared database whose content model differs from this build's (`opticli drift`): write anyway. Takes the fingerprint from the drift error or `opticli drift`, and stops counting when the differences change. Without it such a write asks on a terminal, and elsewhere fails with drift (exit 5). Ask the user first. */
  acceptDrift?: string;
  /** Put the new version in this project (its id or exact name; `opticli projects` lists them), as a draft for review: it takes the place of the content's earlier version in the project, in the same language. Content in another unpublished project is refused (exit 5). Not with --publish or --publish-at: publish or schedule the project's ready items together with `opticli projects publish`. */
  inProject?: string;
  /** With --in-project: also mark the new version Ready to publish, so the project's publish puts it live. Where an approval sequence applies that is refused (exit 3); with --request-approval it goes for review instead (and counts as ready once approved). */
  ready?: boolean;
  /** Schedule the publish instead of publishing now: an ISO 8601 date and time, UTC unless it has an offset: 2025-03-01T08:00Z or 2025-03-01T09:00+01:00. The version stays a draft (delayedPublish) until the CMS's scheduled job publishes it; the rules for --publish apply (other people's drafts, approval sequences). */
  publishAt?: string;
  /** Also publish unpublished changes someone else saved after the published version. Without it such a publish asks on a terminal, and elsewhere fails with a conflict (exit 5) that lists them. Where the site makes new area blocks shared, it also lets an item of a whole-area write that takes over a block of the content's "For this page" folder save the block's new version over a draft someone else saved (without it: a conflict, exit 5, whose details.draft.path names the item). Someone else's drafts of other blocks never go along with --publish: name those in `opticli publish <ref> --with-block`. */
  includeDraft?: boolean;
  /** Base the change on this version instead of the latest: published, or a version (456 or 123_456), of the same content and language. Newer versions (someone's draft) are left out and stay as they are, and with --publish they don't go live. The concurrency check still compares with the latest version (or --base-version). Not with a ref that names a version. */
